// Canonical static deployment workflow installed by Nexora when a repository is linked.
// Keep this byte-for-byte aligned with docs/templates/nexora-deploy.yml.
// Generated by scripts/generate_deploy_workflow.py - do not edit by hand.
export const NEXORA_DEPLOY_WORKFLOW = "name: Nexora artifact staging (static preview)\n\non:\n  workflow_dispatch:\n    inputs:\n      deployment_id:\n        description: Nexora deployment ID\n        required: true\n        type: string\n      commit_sha:\n        description: Immutable commit SHA selected by Nexora\n        required: true\n        type: string\n      output_directory:\n        description: Relative static build output directory configured in Nexora\n        required: true\n        type: string\n        default: dist\n\npermissions:\n  contents: read\n  id-token: write\n\nconcurrency:\n  group: nexora-deployment-${{ inputs.deployment_id }}\n  cancel-in-progress: false\n\njobs:\n  stage-static-artifact:\n    if: github.event_name == 'workflow_dispatch'\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    permissions:\n      contents: read\n      id-token: write\n    env:\n      DEPLOYMENT_ID: ${{ inputs.deployment_id }}\n      EXPECTED_COMMIT: ${{ inputs.commit_sha }}\n      OUTPUT_DIRECTORY: ${{ inputs.output_directory }}\n      NEXORA_API: https://api.nexoraedge.digital\n      OIDC_AUDIENCE: https://api.nexoraedge.digital/github-deployments\n    steps:\n      - name: Check out the exact deployment commit\n        uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683 # v4.2.2\n        with:\n          ref: ${{ inputs.commit_sha }}\n          persist-credentials: false\n          fetch-depth: 1\n\n      - name: Verify immutable source identity\n        shell: bash\n        run: |\n          set -euo pipefail\n          [[ \"$EXPECTED_COMMIT\" =~ ^[a-fA-F0-9]{40}$ ]]\n          actual=\"$(git rev-parse HEAD)\"\n          [[ \"$actual\" == \"$EXPECTED_COMMIT\" ]] || {\n            echo \"Checked-out commit does not match the Nexora deployment request.\" >&2\n            exit 1\n          }\n\n      # Supports npm static projects (npm ci/install + npm run build) and plain\n      # static repositories without a package.json. Build commands run on a\n      # disposable GitHub-hosted runner, never on Nexora servers.\n      - name: Build static site\n        shell: bash\n        run: |\n          set -euo pipefail\n          [[ \"$OUTPUT_DIRECTORY\" =~ ^[A-Za-z0-9._/-]{1,160}$ ]]\n          [[ \"$OUTPUT_DIRECTORY\" != /* ]]\n          [[ \"/$OUTPUT_DIRECTORY/\" != *\"/../\"* ]]\n          [[ \"$OUTPUT_DIRECTORY\" == \".\" ]] || [[ \"/$OUTPUT_DIRECTORY/\" != *\"/./\"* ]]\n          if test -f package.json; then\n            if test -f package-lock.json; then\n              npm ci\n            else\n              npm install --no-audit --no-fund\n            fi\n            npm run build --if-present\n          fi\n          test -d \"$OUTPUT_DIRECTORY\"\n          if find \"$OUTPUT_DIRECTORY\" -type l -print -quit | grep -q .; then\n            echo \"Symbolic links are not permitted in the static output.\" >&2\n            exit 1\n          fi\n          if find \"$OUTPUT_DIRECTORY\" ! -type d ! -type f -print -quit | grep -q .; then\n            echo \"Special files are not permitted in the static output.\" >&2\n            exit 1\n          fi\n\n      - name: Package and stage private artifact\n        shell: bash\n        run: |\n          set -euo pipefail\n          artifact=\"$RUNNER_TEMP/nexora-static.tar.gz\"\n          tar --sort=name --mtime='UTC 1970-01-01' --owner=0 --group=0 --numeric-owner \\\n            --exclude='./.git' \\\n            -C \"$OUTPUT_DIRECTORY\" -czf \"$artifact\" .\n          bytes=\"$(stat -c '%s' \"$artifact\")\"\n          if (( bytes < 1 || bytes > 104857600 )); then\n            echo \"Artifact must be between 1 byte and 100 MiB.\" >&2\n            exit 1\n          fi\n          digest=\"$(sha256sum \"$artifact\" | awk '{print $1}')\"\n\n          oidc_url=\"${ACTIONS_ID_TOKEN_REQUEST_URL}&audience=${OIDC_AUDIENCE}\"\n          oidc_token=\"$(curl --fail --silent --show-error \\\n            -H \"Authorization: Bearer ${ACTIONS_ID_TOKEN_REQUEST_TOKEN}\" \\\n            \"$oidc_url\" | jq -er '.value')\"\n\n          exchange=\"$(curl --fail --silent --show-error \\\n            -X POST \\\n            -H \"Authorization: Bearer $oidc_token\" \\\n            \"$NEXORA_API/v1/github/deployments/$DEPLOYMENT_ID/oidc/exchange\")\"\n          upload_token=\"$(jq -er '.uploadToken' <<<\"$exchange\")\"\n\n          curl --fail --silent --show-error \\\n            -X PUT \\\n            -H \"Authorization: Bearer $upload_token\" \\\n            -H \"Content-Type: application/gzip\" \\\n            -H \"X-Artifact-SHA256: $digest\" \\\n            --data-binary \"@$artifact\" \\\n            \"$NEXORA_API/v1/github/deployments/$DEPLOYMENT_ID/artifact\"\n\n          echo \"Artifact staged privately in Nexora. This workflow does not publish or activate a release.\"\n";

